using System.Globalization;
// var name = ...
// double version = ...

exercises.solution:
using System.Globalization;
var name = "Rust";
double version = 1.85;
Console.WriteLine($"{name} {version.ToString(CultureInfo.InvariantCulture)}");

using System.Globalization;
int x = 100;
double y = x;
Console.WriteLine(y.ToString("0", CultureInfo.InvariantCulture));

const int MaxScore = 100;
const int MinScore = 0;
Console.WriteLine($"{MaxScore} {MinScore}");

var a = 5;
var b = 10;
(a, b) = (b, a);
Console.WriteLine($"{a} {b}");
